**Idea:**  
The current champion only looks two rounds ahead and rewards kills that happen immediately, so it can miss a safe action that would certainly kill a pirate on the third round (the last shot a pirate gets).  
This policy performs a full *depth‑3* search (the whole life‑time of any pirate) assuming we will always pick the best follow‑up actions.  For each possible first move it computes the minimum achievable “HP‑deficit” after up to three rounds, i.e. the smallest total HP that could remain if we play optimally thereafter.  The action that yields the lowest final deficit is chosen; ties are broken by higher total cannon damage and by preferring moves.  By planning to the end of a pirate’s three‑shot window the policy never lets a pirate survive on the death‑square when it could have been killed by a later merge.

```python
NUM_COLUMNS = 5
MAX_POSITION = 3          # reaching this loses the game
INF = 10 ** 9

class Policy:
    name = "deep_three_step_optimal_deficit"

    # --------------------------------------------------------------- #
    def choose_action(self, engine):
        # snapshot
        cannons = {c: engine.cannons[c].damage for c in engine.cannons}
        pirates = [
            {"column": p.column, "position": p.position, "hp": p.hp}
            for p in engine.pirates
        ]

        # ---------- helpers ---------------------------------------- #
        def apply_action(cann_map, act):
            """Return a new cannon map after performing act (spawn or move)."""
            new = dict(cann_map)
            if act[0] == "spawn":
                col = act[1]
                new[col] = new.get(col, 0) + 1          # new cannon damage = 1
            else:  # move
                donor, target = act[1], act[2]
                dmg = new.pop(donor)                     # donor disappears
                new[target] = new.get(target, 0) + dmg   # merge damage
                # pending spawn cannon is lost – nothing else to do
            return new

        def simulate_round(cann_map, pir_list):
            """One full round: damage then advance. Returns (pirates, loss)."""
            pir = [dict(p) for p in pir_list]

            # damage – only the front pirate in each column is hit
            for col, dmg in cann_map.items():
                if dmg <= 0:
                    continue
                col_p = [p for p in pir if p["column"] == col]
                if not col_p:
                    continue
                front = max(col_p, key=lambda p: p["position"])
                front["hp"] -= dmg
                if front["hp"] <= 0:
                    pir.remove(front)

            # advance
            for p in pir:
                p["position"] += 1

            loss = any(p["position"] >= MAX_POSITION for p in pir)
            return pir, loss

        def deficit(cann_map, pir_list):
            """Total HP that cannot be dealt before pirates reach position 3."""
            total = 0
            for p in pir_list:
                steps = MAX_POSITION - p["position"]
                dmg = cann_map.get(p["column"], 0)
                possible = dmg * steps
                need = max(0, p["hp"] - possible)
                total += need
            return total

        def legal_actions(cann_map):
            actions = []
            # spawn actions (including merges)
            for col in range(NUM_COLUMNS):
                actions.append(("spawn", col))
            # move actions (donor must exist)
            for donor in cann_map:
                for target in range(NUM_COLUMNS):
                    if donor == target:
                        continue
                    actions.append(("move", donor, target))
            return actions

        # ---------- recursive optimal look‑ahead ------------------- #
        def best_deficit(cann_map, pir_list, depth):
            """Return the minimum possible deficit after up to `depth` more rounds."""
            # immediate loss?
            if any(p["position"] >= MAX_POSITION for p in pir_list):
                return INF
            if not pir_list:
                return 0
            if depth == 0:
                return deficit(cann_map, pir_list)

            best = INF
            for act in legal_actions(cann_map):
                after_cann = apply_action(cann_map, act)
                after_pir, loss = simulate_round(after_cann, pir_list)
                if loss:
                    continue
                d = best_deficit(after_cann, after_pir, depth - 1)
                if d < best:
                    best = d
            return best

        # ---------- evaluate first actions -------------------------- #
        best_action = None
        best_key = None   # (final_deficit, -total_damage, tie_pref, act)

        for act in legal_actions(cannons):
            # first round
            c1 = apply_action(cannons, act)
            p1, loss1 = simulate_round(c1, pirates)
            if loss1:
                continue

            # look ahead the remaining two rounds (total depth = 3)
            final_def = best_deficit(c1, p1, depth=2)

            total_damage = sum(c1.values())
            tie_pref = 0 if act[0] == "move" else 1   # prefer moves

            key = (final_def, -total_damage, tie_pref, act)

            if best_key is None or key < best_key:
                best_key = key
                best_action = act

        # fallback – should never happen
        if best_action is None:
            for col in range(NUM_COLUMNS):
                if col not in engine.cannons:
                    return ("spawn", col)
            return ("spawn", 0)

        return best_action
```

A column can be cleared without any cannon merges exactly when the total HP of all pirates stacked in that column is ≤ 3 (the cannon’s three‑shot budget).  

